CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, username) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'username', NEW.raw_user_meta_data->>'name', ''),80)); RETURN NEW; END; $$;
CREATE TRIGGER on_signup_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.favorites (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, item_type text NOT NULL CHECK(item_type IN ('film','serie','anime')), item_id text NOT NULL, item jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,item_type,item_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated;
GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_read ON public.favorites FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY favorites_add ON public.favorites FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY favorites_remove ON public.favorites FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.watch_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, item_type text NOT NULL CHECK(item_type IN ('film','serie','anime')), item_id text NOT NULL, item jsonb NOT NULL, viewed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.watch_events TO authenticated;
GRANT ALL ON public.watch_events TO service_role;
ALTER TABLE public.watch_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY views_read ON public.watch_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY views_add ON public.watch_events FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE INDEX views_date ON public.watch_events(viewed_at);
CREATE FUNCTION public.film_rankings(days integer) RETURNS TABLE(item jsonb, views bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (array_agg(w.item ORDER BY w.viewed_at DESC))[1], count(DISTINCT w.user_id) FROM public.watch_events w WHERE auth.uid() IS NOT NULL AND w.item_type='film' AND w.viewed_at >= now() - make_interval(days => greatest(1,least(days,30))) GROUP BY w.item_type,w.item_id ORDER BY count(DISTINCT w.user_id) DESC, max(w.viewed_at) DESC LIMIT 12; $$;
REVOKE ALL ON FUNCTION public.film_rankings(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.film_rankings(integer) TO authenticated;
CREATE POLICY avatars_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);